design.css:
/* Marigold — the KickAssAnime look (docs/theme-references/kickassanime.md): #0F0F0F, Roboto, Material yellow, 4 px corners. */

/* The flush 64 px app bar: the menu button, the search field in the middle, the account button in yellow. */
[data-slot="nav.top"] { background: #101010 !important; border-color: #1e1e1e !important; }
[data-slot="nav.top"] [data-part="search.field"] { height: 40px; border: 0; border-radius: 4px; background: #1e1e1e; font-size: 15px; }
[data-slot="nav.top"] > :last-child { border-radius: 4px; background: #fdd835 !important; color: #212121 !important; }
@media (min-width: 641px) { [data-slot="home"] { padding-top: 24px; } }

/* The menu pinned down the left: 212 × 44 px destinations with a 24 px icon, 8 px apart, no accent
   colour on the page you are on beyond a quiet lift and a yellow icon. */
[data-slot="nav.panel"] { gap: 8px; padding: 24px; border: 0; background: #101010; }
[data-slot="nav.panel"] [data-part="nav.item"] { height: 44px; gap: 16px; padding: 0 8px; border-radius: 4px; color: #fff; font-size: 16px; font-weight: 400; }
[data-slot="nav.panel"] [data-part="nav.item"]:hover { background: rgba(255, 255, 255, 0.08); }
[data-slot="nav.panel"] [data-part="nav.item"][data-active] { background: rgba(255, 255, 255, 0.12); }
[data-slot="nav.panel"] [data-part="nav.item"][data-active] [data-part="nav.item.icon"] { color: #fdd835; }
[data-slot="nav.panel"] [data-part="nav.item.icon"] { width: 24px; }
[data-slot="nav.panel"] [data-part="nav.item.icon"] svg { width: 24px; height: 24px; }

/* Headings. */
[data-part="row.title"], [data-part="block.title"] { font-size: 24px; font-weight: 700; color: #fff; }
[data-part="row.more"] { color: #fdd835; font-size: 13px; font-weight: 700; letter-spacing: 1px; text-transform: uppercase; }

/* ALL / TRENDING / POPULAR: letter-spaced uppercase words, the active one yellow. */
[data-slot="block.tabbed-grid"] [data-part="tabs"] { gap: 6px; padding: 0; border: 0; background: transparent; }
[data-slot="block.tabbed-grid"] [data-part="tab"] { padding: 6px 12px; border-radius: 4px; background: transparent; color: #fff; font-size: 13px; font-weight: 700; letter-spacing: 1.2px; text-transform: uppercase; box-shadow: none; }
[data-slot="block.tabbed-grid"] [data-part="tab"][data-active] { color: #fdd835; }
[data-slot="block.tabbed-grid"] [data-part="tab"] > span { display: none; }

/* Poster cards: a yellow year chip, outlined chips under the title. */
[data-part="kaa.year"] { margin: 6px; padding: 1px 7px; border-radius: 4px; background: #fdd835; }
[data-part="kaa.tv"], [data-part="kaa.chip"] { padding: 1px 6px; border: 1px solid rgba(255, 255, 255, 0.6); border-radius: 4px; color: #fff; }
[data-part="kaa.tv"] { border-color: #fdd835; color: #fdd835; }

/* Today Releases: a raised #1e1e1e card, 310 px wide; a 20 px heading with a yellow MORE, the date and
   a live clock in spaced capitals, then 65 px rows of a 40 × 57 poster, the title and the airing time
   right-aligned behind a yellow tick. */
[data-slot="block.airing-today"] { margin: 0 12px 16px 0; padding: 0 0 16px; border-radius: 4px; background: #1e1e1e; box-shadow: 0 3px 1px -2px rgba(0, 0, 0, 0.2), 0 2px 2px 0 rgba(0, 0, 0, 0.14), 0 1px 5px 0 rgba(0, 0, 0, 0.12); }
[data-slot="block.airing-today"] > :first-child { margin: 0; padding: 16px; align-items: center; }
[data-slot="block.airing-today"] [data-part="block.title"] { font-size: 20px; font-weight: 500; line-height: 32px; letter-spacing: 0.25px; }
[data-slot="block.airing-today"] [data-part="block.more"] { padding: 0 12px; border-radius: 4px; color: #fdd835; font-size: 12px; font-weight: 500; line-height: 28px; letter-spacing: 1.07px; }
[data-slot="block.airing-today"] [data-part="block.more"]:hover { background: rgba(253, 216, 53, 0.08); text-decoration: none; }
[data-part="block.clock"] { margin: 0 16px 8px; color: rgba(255, 255, 255, 0.7); font-size: 14px; font-weight: 500; line-height: 36px; letter-spacing: 1.25px; }
[data-slot="block.airing-today"] ul { gap: 0; padding: 0 16px; }
[data-slot="block.airing-today"] [data-part="block.item"] { height: 65px; gap: 12px; padding: 0 12px; border-radius: 0; }
[data-slot="block.airing-today"] [data-part="block.item"]:hover { background: rgba(255, 255, 255, 0.08); }
[data-part="airing.poster"] { width: 40px; height: 57px; border-radius: 4px; }
[data-part="airing.title"] { color: #fff; font-size: 14px; font-weight: 500; line-height: 16.8px; letter-spacing: 0.1px; }
[data-part="airing.time"] { margin-top: 2px; gap: 8px; color: rgba(255, 255, 255, 0.7); font-size: 12px; letter-spacing: 0.4px; }
[data-part="block.item"][data-aired] [data-part="airing.time"] svg { color: #fdd835; }

/* Series page. */
[data-slot="detail"] [data-part="detail.poster"] { border-radius: 4px; }
[data-slot="detail"] [data-part="tab"][data-active] { color: #fdd835; }
[data-slot="detail"] [data-part="tab"][data-active] > span { background: #fdd835; }
[data-slot="detail"] [data-part="button"][data-variant="primary"] { border-radius: 4px; background: #fdd835; color: #212121; text-transform: uppercase; }

/* Continue Watching: the site's own 143 px portrait card with 4 px corners, a yellow progress bar along
   the bottom of the art, the title in 14 px and the episode as a small chip below. */
[data-part="marigold.cw-bar"] { height: 3px !important; background: rgba(0, 0, 0, 0.6) !important; }
[data-part="marigold.cw-bar"] > * { background: #fdd835 !important; }
[data-part="marigold.cw-meta"] { align-self: flex-start; padding: 1px 6px; border-radius: 3px; background: rgba(255, 255, 255, 0.12); }
